## Verified facts

The repository describes `data/processed/activsg2000_scenarios_v1` as a public synthetic Texas ACTIVSg2000 package labeled for instructional years 2027--2029; those labels are not historical telemetry or forecasts. The documented topology is 2,000 buses, 3,206 branches, and 544 generators, organized into six half-year blocks. The documented horizons are 4,344 hours for January--June in 2027 and 2029, 4,368 hours for January--June in leap year 2028, and 4,416 hours for July--December in every released year. These are hours, not CSV row counts.

The checked-in root and block manifests are documented as `validation_status: unverified_dependency` because `highspy` is unavailable. That is not a passed validation. The validator changes the manifests to `passed` only after all 26,304 hourly states are feasible in a complete HiGHS-backed run; a partial smoke run never produces a usable production manifest.

## Complete executable inspection

Save the following as the repository-relative file `work/tutorial/inspect_activsg2000_package.py`. It uses only the Python standard library:

```python
from __future__ import annotations

import argparse
import csv
import json
import tempfile
from pathlib import Path
from typing import Any

def json_shape(value: Any) -> str:
    if isinstance(value, list):
        return f"list[{len(value)}]"
    if isinstance(value, dict):
        return f"object[{len(value)} keys]"
    return type(value).__name__

def key_columns(columns: list[str]) -> list[str]:
    candidates = [["bus_id"], ["branch_id"], ["generator_id"], ["site_id"], ["team_id", "site_id"], ["from_bus", "to_bus"], ["from_bus_id", "to_bus_id"]]
    return next((candidate for candidate in candidates if set(candidate) <= set(columns)), [])

def read_csv(path: Path) -> tuple[list[str], list[dict[str, str]]]:
    with path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        return [str(column) for column in (reader.fieldnames or [])], list(reader)

def discover_bus_ids(package: Path) -> set[str]:
    ids: set[str] = set()
    for path in sorted(package.rglob("*.csv")):
        try:
            columns, rows = read_csv(path)
        except (OSError, csv.Error):
            continue
        column = next((name for name in ("bus_id", "bus", "BUS_I") if name in columns), None)
        if column is not None:
            ids.update(row[column] for row in rows if row.get(column, "") != "")
    return ids

def inspect(package: Path) -> dict[str, Any]:
    if not package.is_dir():
        raise FileNotFoundError(f"package directory does not exist: {package}")
    bus_ids = discover_bus_ids(package)
    report: dict[str, Any] = {"package": str(package), "files": [], "manifest_statuses": []}
    for path in sorted(package.rglob("*")):
        if not path.is_file() or path.suffix.lower() not in {".json", ".csv"}:
            continue
        relative = path.relative_to(package).as_posix()
        item: dict[str, Any] = {"path": relative}
        if path.suffix.lower() == ".json":
            data = json.loads(path.read_text(encoding="utf-8"))
            item.update({"kind": "json", "shape": json_shape(data), "missing_values": None, "duplicate_keys": None})
            if isinstance(data, dict):
                item["keys"] = sorted(data)
                if "validation_status" in data:
                    status = data["validation_status"]
                    item["validation_status"] = status
                    report["manifest_statuses"].append({"path": relative, "validation_status": status})
                metadata = {key: data[key] for key in ("horizon_hours", "horizon", "hours", "year", "round") if key in data}
                if metadata:
                    item["metadata"] = metadata
        else:
            columns, rows = read_csv(path)
            keys = key_columns(columns)
            missing = {column: sum(row.get(column, "") == "" for row in rows) for column in columns}
            duplicate_count = None
            if keys:
                seen: set[tuple[str, ...]] = set()
                duplicate_count = 0
                for row in rows:
                    key = tuple(row.get(column, "") for column in keys)
                    if key in seen:
                        duplicate_count += 1
                    seen.add(key)
            item.update({"kind": "csv", "shape": [len(rows), len(columns)], "columns": columns, "missing_values": {key: value for key, value in missing.items() if value}, "key_columns": keys, "duplicate_keys": duplicate_count})
            references = [column for column in ("bus_id", "bus", "BUS_I", "from_bus", "to_bus", "from_bus_id", "to_bus_id") if column in columns]
            if bus_ids and references:
                item["bus_references_not_in_discovered_bus_catalog"] = {column: sorted({row[column] for row in rows if row.get(column, "") and row[column] not in bus_ids}) for column in references}
        report["files"].append(item)
    return report

def self_test() -> None:
    with tempfile.TemporaryDirectory() as directory:
        package = Path(directory) / "fixture"
        package.mkdir()
        (package / "bus.csv").write_text("bus_id,demand_mw\n1,10\n2,12\n", encoding="utf-8")
        (package / "branch.csv").write_text("from_bus,to_bus\n1,2\n", encoding="utf-8")
        (package / "manifest.json").write_text("{\"validation_status\":\"unverified_dependency\",\"horizon_hours\":2}", encoding="utf-8")
        report = inspect(package)
        assert {item["path"] for item in report["files"]} == {"branch.csv", "bus.csv", "manifest.json"}
        assert report["manifest_statuses"] == [{"path": "manifest.json", "validation_status": "unverified_dependency"}]
        print("synthetic fixture inspection passed")

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("package", type=Path, nargs="?")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test:
        self_test()
    elif args.package is not None:
        print(json.dumps(inspect(args.package), indent=2, sort_keys=True))
    else:
        parser.error("provide a package path or --self-test")

if __name__ == "__main__":
    main()
```

Run the small test first, then inspect the released package from the repository root:

```bash
python work/tutorial/inspect_activsg2000_package.py --self-test
python work/tutorial/inspect_activsg2000_package.py data/processed/activsg2000_scenarios_v1
```

The output lists every JSON/CSV file read, JSON keys and shape, CSV columns and shape, CSV missing-value counts, recognizable duplicate-key counts, discovered bus-reference discrepancies, JSON horizon metadata, and observed manifest statuses. A discovered file is an inspection input; its meaning must be confirmed from its path and keys/columns. Empty bus-reference discrepancy lists are evidence only for that check, not full validation. For JSON, missing-value and duplicate-key counts are not applicable and are reported as null.

## Interpretations and unknowns

A duplicate key or an out-of-catalog bus reference is an inspection finding, not by itself proof that the entire package is invalid. The actual keys, columns, row counts, missing values, duplicate counts, bus references, and manifest values in a particular checkout remain unknown until the command runs. The synthetic fixture does not establish the released package schema or contents.

## Verification checklist

- Use only the listed public repository files and synthetic or instructor-approved fixtures; never inspect private team submissions.
- Run `--self-test` before the released-package command.
- Record the exact package-relative files reported by the output.
- Review JSON keys/shapes and CSV columns/shapes, missing values, and duplicate keys.
- Review bus references against the bus catalog discovered by the script.
- Record horizon metadata in hours and preserve every observed manifest status.
- Treat `unverified_dependency` as non-passed; claim full validation only when the relevant manifest says `passed`.
- Do not report this inspection, a partial smoke run, or empty discrepancy lists as DCOPF feasibility validation.
